import os


class Config:
    """
    Configuration module for NYC Taxi Fare Prediction.
    Defines file paths, data constraints, feature engineering constants,
    and model hyperparameters.
    """

    # ==========================================
    # Project Directories & File Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"
    SUBMISSION_DIR = "./submission"

    # Data Paths (generated by metadata script)
    TRAIN_DATA_PATH = os.path.join(METADATA_DIR, "train.parquet")
    VAL_DATA_PATH = os.path.join(METADATA_DIR, "val.parquet")
    TEST_DATA_PATH = os.path.join(METADATA_DIR, "test.parquet")

    # Submission Output
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Cache Directory for intermediate files (e.g., processed features)
    CACHE_DIR = os.path.join(WORKING_DIR, "idea_1")

    # ==========================================
    # Global Settings
    # ==========================================
    RANDOM_SEED = 42

    # Debug Mode: If True, uses a smaller subset of data for rapid iteration
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 100_000

    # ==========================================
    # Data Cleaning Constraints
    # ==========================================
    # Bounding Box for NYC + Airports (JFK, LGA, EWR)
    # Filters out erroneous GPS coordinates outside the metropolitan area
    MIN_LON = -74.50
    MAX_LON = -72.80
    MIN_LAT = 40.50
    MAX_LAT = 41.80

    # Target Variable Constraints
    MIN_FARE = 2.50
    MAX_FARE = 500.00

    # Passenger Constraints
    MIN_PASSENGERS = 1
    MAX_PASSENGERS = 10

    # ==========================================
    # Feature Engineering Constants
    # ==========================================
    # Coordinates for major airports to calculate distance-to-airport features
    AIRPORTS = {
        "JFK": {"lat": 40.6413, "lon": -73.7781},
        "LGA": {"lat": 40.7769, "lon": -73.8740},
        "EWR": {"lat": 40.6895, "lon": -74.1745},
    }
    # Threshold radius (in degrees) to consider a location "at" an airport
    AIRPORT_RADIUS = 0.02

    # ==========================================
    # Model Hyperparameters (SGD Regressor)
    # ==========================================
    MODEL_PARAMS = {
        "loss": "squared_error",
        "penalty": "l2",
        "alpha": 0.0001,
        "l1_ratio": 0.15,
        "fit_intercept": True,
        "max_iter": 1000,
        "tol": 1e-3,
        "shuffle": True,
        "random_state": RANDOM_SEED,
        "learning_rate": "invscaling",
        "eta0": 0.01,
        "power_t": 0.25,
        "average": False,
    }

    # Training Loop Settings
    NUM_EPOCHS = 1  # Single pass is often sufficient for large datasets with SGD
    BATCH_SIZE = 4096  # Batch size for incremental learning/processing

    @classmethod
    def setup(cls):
        """
        Creates necessary directories for the project.
        Should be called at the start of execution.
        """
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)

    @classmethod
    def get_model_params(cls):
        """Returns a copy of the model hyperparameters."""
        return cls.MODEL_PARAMS.copy()
